mapper.select:
select 
from approval_instance
where instance_id = #{instanceId}

select 
from approval_instance
where idempotency_key = #{idempotencyKey}

select 
from approval_instance
where business_code = #{businessCode}
  and business_id = #{businessId}
  and business_round = #{businessRound}

select 
from approval_instance i
left join approval_template template
  on template.template_id = i.template_id
left join approval_task current_task
  on current_task.instance_id = i.instance_id
 and current_task.node_id = i.current_node_id

    and i.instance_id = #{instanceId}

        and i.business_code = #{businessCode}


        and i.business_source = #{businessSource}


        and i.business_id = #{businessId}

    and i.status = #{status}

        and i.callback_status = #{callbackStatus}


        and i.applicant_user_id = #{applicantUserId}

    and i.anchor_dept_id = #{anchorDeptId}

order by i.started_time desc, i.instance_id desc

select count(*)
from approval_instance i
where i.instance_id = #{instanceId}
  and (
      i.applicant_user_id = #{userId}
      or exists (
          select 1 from approval_task_candidate participant_candidate
          where participant_candidate.instance_id = i.instance_id
            and participant_candidate.user_id = #{userId}
      )
      or exists (
          select 1 from approval_action_log participant_action
          where participant_action.instance_id = i.instance_id
            and participant_action.operator_user_id = #{userId}
      )
  )

mapper.update:
update approval_instance
set status = #{instance.status},
    current_node_id = #{instance.currentNodeId},
    current_node_order = #{instance.currentNodeOrder},
    callback_status = #{instance.callbackStatus},
    approved_action_count = #{instance.approvedActionCount},
    finished_time = #{instance.finishedTime},
    lock_version = lock_version + 1,
    update_by = #{instance.updateBy}, update_time = sysdate(),
    remark = #{instance.remark}
where instance_id = #{instance.instanceId}
  and status = #{expectedStatus}
  and lock_version = #{expectedVersion}

update approval_task
set task_status = #{task.taskStatus},
    required_count = #{task.requiredCount},
    completed_count = #{task.completedCount},
    activated_time = #{task.activatedTime},
    completed_time = #{task.completedTime},
    lock_version = lock_version + 1,
    update_by = #{task.updateBy}, update_time = sysdate(),
    remark = #{task.remark}
where task_id = #{task.taskId}
  and task_status = #{expectedStatus}
  and lock_version = #{expectedVersion}

update approval_task_candidate
set candidate_status = #{candidate.candidateStatus},
    candidate_reason = #{candidate.candidateReason},
    acted_time = #{candidate.actedTime},
    lock_version = lock_version + 1,
    update_by = #{candidate.updateBy}, update_time = sysdate(),
    remark = #{candidate.remark}
where candidate_id = #{candidate.candidateId}
  and candidate_status = #{expectedStatus}
  and lock_version = #{expectedVersion}

update approval_task
set task_status = 'CANCELLED', completed_time = sysdate(),
    lock_version = lock_version + 1, update_by = #{updateBy},
    update_time = sysdate(), remark = #{reason}
where instance_id = #{instanceId}
  and task_status in ('WAITING', 'PENDING')
